PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, suspended_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE organization (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, logo TEXT, metadata TEXT, suspended_at INTEGER, deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE member (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','admin','editor','viewer')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,user_id));
CREATE INDEX member_user_idx ON member(user_id);
CREATE TABLE workspace_settings (organization_id TEXT PRIMARY KEY REFERENCES organization(id) ON DELETE CASCADE, ai_provider TEXT NOT NULL DEFAULT 'workers-ai', encrypted_provider_key TEXT, retention_days INTEGER NOT NULL DEFAULT 30, monthly_ocr_limit INTEGER NOT NULL DEFAULT 100, max_documents INTEGER NOT NULL DEFAULT 250, max_storage_bytes INTEGER NOT NULL DEFAULT 524288000, max_members INTEGER NOT NULL DEFAULT 25, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE collection (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, color TEXT NOT NULL DEFAULT '#5b5bd6', restricted INTEGER NOT NULL DEFAULT 0, created_by TEXT NOT NULL REFERENCES user(id), deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX collection_org_idx ON collection(organization_id,deleted_at);
CREATE TABLE document (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id) ON DELETE CASCADE, collection_id TEXT REFERENCES collection(id), title TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, bytes INTEGER NOT NULL, checksum TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'uploading', current_version_id TEXT, created_by TEXT NOT NULL REFERENCES user(id), deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,checksum));
CREATE INDEX document_org_status_idx ON document(organization_id,status,deleted_at);
CREATE TABLE document_version (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, document_id TEXT NOT NULL REFERENCES document(id) ON DELETE CASCADE, version INTEGER NOT NULL, r2_key TEXT NOT NULL, checksum TEXT NOT NULL, pages INTEGER, extracted_characters INTEGER NOT NULL DEFAULT 0, chunk_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'extracting', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(document_id,version));
CREATE TABLE chunk (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, document_id TEXT NOT NULL REFERENCES document(id) ON DELETE CASCADE, version_id TEXT NOT NULL REFERENCES document_version(id) ON DELETE CASCADE, collection_id TEXT, ordinal INTEGER NOT NULL, content TEXT NOT NULL, heading TEXT, page INTEGER, start_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL, content_hash TEXT NOT NULL, vector_id TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(version_id,ordinal));
CREATE INDEX chunk_org_document_idx ON chunk(organization_id,document_id);
CREATE VIRTUAL TABLE chunk_fts USING fts5(content, heading, chunk_id UNINDEXED, organization_id UNINDEXED, version_id UNINDEXED, tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER chunk_fts_insert AFTER INSERT ON chunk BEGIN INSERT INTO chunk_fts(content,heading,chunk_id,organization_id,version_id) VALUES(new.content,new.heading,new.id,new.organization_id,new.version_id); END;
CREATE TRIGGER chunk_fts_delete AFTER DELETE ON chunk BEGIN DELETE FROM chunk_fts WHERE chunk_id=old.id; END;
CREATE TRIGGER chunk_fts_update AFTER UPDATE OF content,heading ON chunk BEGIN DELETE FROM chunk_fts WHERE chunk_id=old.id; INSERT INTO chunk_fts(content,heading,chunk_id,organization_id,version_id) VALUES(new.content,new.heading,new.id,new.organization_id,new.version_id); END;
CREATE TABLE ingestion_job (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, document_id TEXT NOT NULL, version_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', progress INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, error_code TEXT, error_message TEXT, started_at INTEGER, completed_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_id,idempotency_key));
CREATE INDEX ingestion_state_idx ON ingestion_job(state,updated_at);
CREATE TABLE conversation (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, user_id TEXT NOT NULL, title TEXT NOT NULL, scope_json TEXT NOT NULL DEFAULT '{}', deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX conversation_org_user_idx ON conversation(organization_id,user_id,updated_at);
CREATE TABLE message (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, conversation_id TEXT NOT NULL REFERENCES conversation(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, confidence REAL, latency_ms INTEGER, input_tokens INTEGER, output_tokens INTEGER, no_answer INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE citation (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, message_id TEXT NOT NULL REFERENCES message(id) ON DELETE CASCADE, document_id TEXT NOT NULL, version_id TEXT NOT NULL, chunk_id TEXT NOT NULL, page INTEGER, excerpt TEXT NOT NULL, score REAL NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE api_key (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT NOT NULL, prefix TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, scopes_json TEXT NOT NULL, created_by TEXT NOT NULL, last_used_at INTEGER, expires_at INTEGER, revoked_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE usage_daily (organization_id TEXT NOT NULL, day TEXT NOT NULL, requests INTEGER NOT NULL DEFAULT 0, ai_neurons REAL NOT NULL DEFAULT 0, storage_bytes INTEGER NOT NULL DEFAULT 0, vector_dimensions INTEGER NOT NULL DEFAULT 0, queue_operations INTEGER NOT NULL DEFAULT 0, no_answers INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(organization_id,day));
CREATE TABLE audit_log (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, actor_id TEXT, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, ip_hash TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE INDEX audit_org_created_idx ON audit_log(organization_id,created_at);
